<?php
require_once __DIR__.'/../app.php';require_once __DIR__.'/../ui.php';require_once __DIR__.'/../filters.php';require_once __DIR__.'/../snapshot_ui.php';require_staff();
handle_post(function(){
    $action=request_string($_POST,'action');$id=(int)($_POST['id']??0);
    if($action==='save'){save_grade($_POST);return;}
    if($action==='review'){review_legacy_grade($id,text_value($_POST,'reason',1000));return;}
    if($action==='delete'){
        $g=grade_record($id,true);revision_check($g,$_POST);grade_editable($g);if($g['published_at']||$g['submitted_at'])throw new DomainException('Previously submitted or published grades must be retained.');
        query('DELETE FROM grades WHERE id=?',[$id]);grade_history($id,'grade_delete',text_value($_POST,'reason',1000),$g);return;
    }
    transition_grade($id,$action,request_string($_POST,'reason'),(int)($_POST['revision']??0));
},'grades.php');
$edit=isset($_GET['edit'])?grade_record(positive_id($_GET['edit'])):null;
$historyGrade=isset($_GET['history'])?grade_record(positive_id($_GET['history'])):null;
$offeringId=(int)($_GET['offering_id']??($edit['offering_id']??0));$o=$offeringId?offering($offeringId):null;
[$where,$params]=grade_filters($_GET);$total=(int)scalar('SELECT COUNT(*) FROM ('.grade_select()." WHERE $where) counted",$params);$page=min(max(1,(int)($_GET['page']??1)),max(1,(int)ceil($total/15)));$offset=($page-1)*15;$data=rows(grade_select()." WHERE $where ORDER BY g.id DESC LIMIT 15 OFFSET $offset",$params);
page_start('Student grades','ISU scale: 1.00 highest · 3.00 passing · 5.00 failed. Official results require publication.');
?><section class="panel no-print"><details><summary>Search and filter grades</summary><form method="get" class="filter-grid mt-3"><?php grade_filter_form($_GET);?><div class="field align-self-end"><button class="btn btn-outline-primary">Apply filters</button> <a href="grades.php">Reset</a></div></form></details></section>
<section class="panel no-print"><h2><?= $edit?'Edit draft #'.(int)$edit['id']:'Enter a grade'?></h2><form method="get" class="filter-grid"><?php select_field('offering_id','Choose an assigned offering',offerings_choices(),$offeringId);?><div class="field align-self-end"><button class="btn btn-outline-primary">Load class roster</button></div></form>
<?php if($o):$p=policy((int)($edit['policy_id']??$o['policy_id']?:1));?><p class="mt-3 policy-note">Policy: <?=h($p['name'])?> · Midterm <?=h($p['midterm_weight'])?>% / final <?=h(100-(float)$p['midterm_weight'])?>% · <?=h($p['rounding'])?> integer conversion · <?= $p['is_approved']?'Approved':'Application default awaiting institutional approval'?></p>
<form method="post" class="form-grid" id="grade-form"><?php csrf_field();?><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><input type="hidden" name="revision" value="<?=(int)($edit['revision']??0)?>"><input type="hidden" name="offering_id" value="<?=(int)$o['id']?>"><?php $roster=array_column(rows("SELECT s.id,CONCAT(s.student_number,' · ',s.full_name) AS label FROM enrollments e JOIN students s ON s.id=e.student_id WHERE e.offering_id=? AND e.status='Enrolled' ORDER BY s.full_name",[$o['id']]),'label','id');select_field('student_id','Enrolled student',$roster,$edit['student_id']??'');input_field('midterm','Midterm / passing standing',$edit['midterm']??'','number',true,'min="0" max="100" step="0.01"');input_field('final','Final / passing standing',$edit['final']??'','number',true,'min="0" max="100" step="0.01"');select_field('result_type','Result',['Numeric'=>'Numeric','INC'=>'INC — unmet requirements'],($edit['remarks']??'')==='INC'?'INC':'Numeric');input_field('inc_reason','Unmet requirements (required for INC)',$edit['inc_reason']??'','text',false,'maxlength="1000"');input_field('completion_reference','Registrar completion form / receipt reference',$edit['completion_reference']??'','text',false,'maxlength="190"');input_field('reason','Change reason / correction reference','','text',(bool)$edit,'maxlength="1000"');?><output class="wide policy-note" id="grade-preview">Enter marks to preview the calculated result.</output><div class="wide"><button class="btn btn-primary" name="action" value="save">Save draft</button> <a href="grades.php">Cancel</a></div></form>
<script type="application/json" id="grade-policy"><?=json_encode(['midterm_weight'=>$p['midterm_weight'],'rounding'=>$p['rounding']],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?></script><script src="assets/js/grading.js" defer></script><?php endif;?></section>
<section class="panel"><?php data_table($data,['id'=>'ID','full_name'=>'Student','subject_code'=>'Subject','section_name'=>'Section','term_name'=>'Term','average'=>'Percentage','gpa'=>'ISU grade','remarks'=>'Result','workflow'=>'Workflow','migration_review'=>'Legacy review'],function($g){
    echo '<a class="btn btn-sm btn-outline-primary" href="?edit='.(int)$g['id'].'">Open</a> <a class="btn btn-sm btn-outline-secondary" href="?history='.(int)$g['id'].'">History</a>';
    echo '<form method="post" class="grade-actions mt-2" data-confirm="Apply this grade action?">';csrf_field();echo '<input type="hidden" name="id" value="'.(int)$g['id'].'"><input type="hidden" name="revision" value="'.(int)$g['revision'].'"><input class="form-control form-control-sm" name="reason" placeholder="Reason / approval reference" maxlength="1000">';
    if($g['migration_review']){if(is_admin())echo '<button class="btn btn-sm btn-warning" name="action" value="review">Review & recalculate</button>';}
    else{if($g['workflow']==='Draft')echo '<button class="btn btn-sm btn-primary" name="action" value="submit">Submit</button><button class="btn btn-sm btn-outline-danger" name="action" value="delete">Delete draft</button>';
        if(is_admin()){if($g['workflow']==='Submitted')echo '<button class="btn btn-sm btn-primary" name="action" value="approve">Approve</button>';if($g['workflow']==='Approved')echo '<button class="btn btn-sm btn-success" name="action" value="publish">Publish</button>';if(in_array($g['workflow'],['Submitted','Approved'],true))echo '<button class="btn btn-sm btn-outline-secondary" name="action" value="return">Return</button>';echo '<button class="btn btn-sm btn-outline-danger" name="action" value="reopen">Reopen / extend</button>';}}
    echo '</form>';
});pagination($total,$page);?></section>
<?php if($historyGrade):$g=$historyGrade;?><section class="panel"><h2>History · grade #<?=(int)$g['id']?></h2><?php foreach(rows('SELECT h.*,u.full_name FROM grade_history h LEFT JOIN users u ON u.id=h.actor_id WHERE grade_id=? ORDER BY h.id DESC',[$g['id']])as $history):?><details class="history-entry"><summary><?=h($history['created_at'].' · '.$history['action'].' · '.($history['full_name']??'System'))?></summary><p><?=h($history['reason'])?></p><div class="two-column"><div><h3 class="h6">Before</h3><?php academic_snapshot($history['before_data']);?></div><div><h3 class="h6">After</h3><?php academic_snapshot($history['after_data']);?></div></div></details><?php endforeach;?></section><?php endif;page_end();
